export const isPhone=p=>p?.type==='phone'&&p.phoneProfile?.reviewed===true;
const ease=t=>{const x=Math.max(0,Math.min(1,t));return x*x*x*(x*(x*6-15)+10);};
export function phoneHold(profile,time,reduced=false,rest){
 const t=Number.isFinite(time)?Math.max(0,time):0,reach=reduced?1:ease(t/.8)*(1-ease((t-3.5)/.9)),turn=reduced?0:t<1?0:t<1.9?.42*ease((t-1)/.9):t<2.4?.42:t<3.3?.42*(1-ease((t-2.4)/.9)):0,k=.11*.4,width=profile.widthMM*k,height=profile.heightMM*k,baseY=30,z=11,co=Math.cos(turn),si=Math.sin(turn),grips=[{x:-width/2,y:height*.25},{x:width/2,y:height*.49}];
 const hands=grips.map((h,i)=>{const a=rest?.[i]||{x:(i?1:-1)*10,y:22,z:1.5},b={x:h.x*co,y:baseY+h.y,z:z-h.x*si};return{x:a.x+(b.x-a.x)*reach,y:a.y+(b.y-a.y)*reach,z:a.z+(b.z-a.z)*reach};});
 return{reach,turn,hands,baseY:(hands[0].y+hands[1].y)/2-height*.37,z:(hands[0].z+hands[1].z)/2,visible:reduced||reach>.02};
}
export function phoneFactsHTML(p,esc){if(!isPhone(p))return '';const a=p.phoneProfile;return `<section class="frame-facts phone-facts"><h4>Selected handset reference</h4><p><strong>${esc(p.colorName)} · ${esc(p.sizes[0])}</strong> · ${p.collectionReference===66?'reference':'carrier SKU'} ${esc(p.referenceSKU)}.</p><p>Published width × height × depth: <strong>${a.widthMM} × ${a.heightMM} × ${a.depthMM} mm</strong> · ${a.weightGrams} g. Screen: ${a.displayInches}-inch OLED; rounded corners reduce viewable area.</p><p>Aluminum frame, glass back, two vertically aligned rear cameras and USB-C. The US hardware reference uses eSIM; no physical SIM tray is modeled.</p><p>${esc(p.sourceOfferNote)}</p><p>${esc(a.photoNote)}</p><p>Original unlettered 3D geometry and a neutral screen. Inspection shows the back and edges; the game activates no wireless plan, calls, camera, microphone, biometric authentication or operating system.</p><a href="${esc(a.manufacturerSource)}" target="_blank" rel="noopener noreferrer">Manufacturer specifications ↗</a><p>Photograph: ${esc(a.photoAuthor)} · <a href="${esc(a.photoLicenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(a.photoLicense||'CC BY-SA 4.0')}</a> · orientation normalized where needed, resized and WebP encoded.</p></section>`;}
export function phoneNotebookHTML(st,esc){return `<div class="modal-body phone-notebook"><span class="eyebrow">HANDSET STUDY · FREE TO READ</span><h3>Compare the body and selected format.</h3><p>These two references are the same iPhone 16 body in different finishes. Both selected carrier listings are 128GB; a back photograph cannot establish storage or US hardware region.</p><div class="phone-study-grid">${st.products.filter(isPhone).map(p=>`<article><h4>${esc(p.name)}</h4><div class="phone-outline" style="--phone-study-color:${esc(p.color)}" aria-hidden="true"><i></i><i></i></div><p>${p.phoneProfile.widthMM} mm wide · ${p.phoneProfile.heightMM} mm tall · ${p.phoneProfile.depthMM} mm deep</p><p>${esc(p.sizes[0])} · ${p.phoneProfile.weightGrams} g</p><button class="button secondary wide" data-action="detail" data-id="${esc(p.id)}">Inspect ${esc(p.colorName)} & source</button></article>`).join('')}</div><p class="hint">The outlines are original comparison diagrams, not a fit guarantee or a screen-size simulation. Free comparison pauses time, charges nothing, reserves no stock and awards no XP. A handset inspection takes six displayed game minutes.</p><button class="button secondary wide" data-action="collection-open">Back to the collection desk</button></div>`;}
